const OV_SCREENS=[{"id": "ov-products", "useCase": "OV-1", "phase": "Product Overview", "title": "BookCover", "subtitle": "AI-powered member retention \u00b7 Three core products", "explanation": "BookCover is an AI-powered member retention platform for health plans across Medicare Advantage, Medicaid, IFP, and D-SNP. Three core products work together: the Member Application (this demo), the Retention Team Platform, and Dedicated Retention Consulting.", "bullets": ["&#8593;10% member retention improvement across product lines", "12&#xd7; more member touchpoints vs 1\u20132 per year traditionally", "&#8595;20% reduction in routine member service costs", "95% retention rates achieved with some clients", "\u2018This Demo\u2019 badge highlights the Member Application \u2014 what prospects are seeing"], "frame": "phone"}, {"id": "ov-why", "useCase": "OV-2", "phase": "The Problem + Differentiation", "title": "Why BookCover", "subtitle": "Retention crisis + what makes us different", "explanation": "The carrier market faces a fundamental retention crisis: under-investment in individual member engagement while the $60B broker/FMO industry is explicitly incentivized to move members at AEP. BookCover addresses this with individual-level AI engagement, FHIR integration, and embedded consulting.", "bullets": ["Brokers/FMOs: $60B market growing to $90B by 2030 \u2014 incentivized to churn", "FHIR API integration \u2014 no custom IT project, uses existing CMS-mandated APIs", "Magic Link onboarding: member active in under 60 seconds, no app download", "BookCover does not collect commissions \u2014 succeeds only when members stay", "CMS compliance monitoring and CAHPS readiness built into every workflow"], "frame": "phone"}];
const OV_HTML=["<div style=\"display:flex;flex-direction:column;height:100%;background:#f5faf6;font-family:'DM Sans',sans-serif\"><div style=\"background:#1d9e75;padding:14px 14px 16px;flex-shrink:0;text-align:center\"><div style=\"display:inline-flex;align-items:center;gap:8px;margin-bottom:10px\"><div style=\"width:36px;height:36px;background:rgba(255,255,255,.18);border-radius:10px;display:flex;align-items:center;justify-content:center\"><svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"white\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/><path d=\"M9 12l2 2 4-4\"/></svg></div><div style=\"font-size:20px;font-weight:900;color:white;letter-spacing:-.5px\">BookCover</div></div><div style=\"font-size:11px;color:rgba(255,255,255,.8);line-height:1.6\">AI-powered member retention for health plans across<br>Medicare Advantage &middot; Medicaid &middot; IFP &middot; D-SNP</div></div><div style=\"flex:1;overflow-y:auto;padding:10px;display:flex;flex-direction:column;background:#f5faf6\"><div style=\"display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px\"><div style=\"background:white;border-radius:10px;border:0.5px solid #d4ead9;padding:10px 12px;text-align:center\"><div style=\"font-size:22px;font-weight:900;color:#1d9e75;letter-spacing:-1px\">&#8593;10%</div><div style=\"font-size:9px;color:#64748B;margin-top:2px;line-height:1.4\">Member retention improvement</div></div><div style=\"background:white;border-radius:10px;border:0.5px solid #d4ead9;padding:10px 12px;text-align:center\"><div style=\"font-size:22px;font-weight:900;color:#1d9e75;letter-spacing:-1px\">12&#xd7;</div><div style=\"font-size:9px;color:#64748B;margin-top:2px;line-height:1.4\">More member touchpoints per year</div></div><div style=\"background:white;border-radius:10px;border:0.5px solid #d4ead9;padding:10px 12px;text-align:center\"><div style=\"font-size:22px;font-weight:900;color:#085041;letter-spacing:-1px\">&#8595;20%</div><div style=\"font-size:9px;color:#64748B;margin-top:2px;line-height:1.4\">Routine member service costs</div></div><div style=\"background:white;border-radius:10px;border:0.5px solid #d4ead9;padding:10px 12px;text-align:center\"><div style=\"font-size:22px;font-weight:900;color:#0F7B5C;letter-spacing:-1px\">95%</div><div style=\"font-size:9px;color:#64748B;margin-top:2px;line-height:1.4\">Retention rate achieved in some clients</div></div></div><div style=\"font-size:9px;font-weight:700;color:#085041;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px\">Three Core Products</div><div style=\"background:#f5faf6;border:1.5px solid #1d9e75;border-radius:10px;padding:10px 12px;margin-bottom:7px\"><div style=\"display:flex;align-items:center;gap:9px\"><div style=\"width:32px;height:32px;background:#1d9e75;border-radius:9px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:16px\">&#128241;</div><div><div style=\"font-size:12px;font-weight:700;color:#0F172A\">1. Member Application<span style=\"background:#1d9e75;color:white;font-size:7px;font-weight:800;padding:2px 6px;border-radius:8px;margin-left:5px\">THIS DEMO</span></div><div style=\"font-size:10px;color:#64748B;margin-top:2px;line-height:1.5\">White-labeled mobile website. Personalized coverage, Rx pricing, benefits, and AI plan guidance \u2014 branded as your health plan.</div></div></div></div><div style=\"background:white;border:0.5px solid #d4ead9;border-radius:10px;padding:10px 12px;margin-bottom:7px\"><div style=\"display:flex;align-items:center;gap:9px\"><div style=\"width:32px;height:32px;background:#f5faf6;border-radius:9px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:16px\">&#128200;</div><div><div style=\"font-size:12px;font-weight:700;color:#0F172A\">2. Retention Team Platform</div><div style=\"font-size:10px;color:#64748B;margin-top:2px;line-height:1.5\">Agent dashboard with individual risk scores, NBA queue, campaign management, and CAHPS readiness tracking.</div></div></div></div><div style=\"background:white;border:0.5px solid #d4ead9;border-radius:10px;padding:10px 12px;margin-bottom:7px\"><div style=\"display:flex;align-items:center;gap:9px\"><div style=\"width:32px;height:32px;background:#f5faf6;border-radius:9px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:16px\">&#128101;</div><div><div style=\"font-size:12px;font-weight:700;color:#0F172A\">3. Dedicated Retention Consulting</div><div style=\"font-size:10px;color:#64748B;margin-top:2px;line-height:1.5\">Embedded team that builds, manages, and optimizes your retention campaigns end-to-end.</div></div></div></div></div><div style=\"background:#f5faf6;border-top:1px solid #d4ead9;padding:5px;text-align:center;font-size:8px;color:#94A3B8;flex-shrink:0\">&#128274; SOC 2 Type II &middot; HIPAA-aligned &middot; Data hosted in United States</div></div><style>@keyframes spin{to{transform:rotate(360deg)}}</style>", "<div style=\"display:flex;flex-direction:column;height:100%;background:#f5faf6;font-family:'DM Sans',sans-serif\"><div style=\"background:#1d9e75;padding:7px 12px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between\"><div style=\"display:flex;align-items:center;gap:7px\"><div style=\"width:20px;height:20px;background:rgba(255,255,255,.18);border-radius:6px;display:flex;align-items:center;justify-content:center\"><svg width=\"9\" height=\"9\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"white\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/><path d=\"M9 12l2 2 4-4\"/></svg></div><div style=\"font-size:11px;font-weight:800;color:white;letter-spacing:-.2px\">BookCover</div></div><div style=\"display:flex;gap:8px;align-items:center\"><svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"rgba(255,255,255,.7)\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"/></svg><svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"rgba(255,255,255,.7)\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 20c0-4 3.6-7 8-7s8 3 8 7\"/></svg></div></div><div style=\"flex:1;overflow-y:auto;padding:10px;display:flex;flex-direction:column;background:#f5faf6\"><div style=\"font-size:9px;font-weight:700;color:#085041;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px\">The Retention Problem</div><div style=\"background:white;border-radius:9px;border:0.5px solid #d4ead9;padding:9px 11px;margin-bottom:6px;display:flex;gap:9px;align-items:flex-start\"><div style=\"width:8px;height:8px;background:#1d9e75;border-radius:50%;flex-shrink:0;margin-top:3px\"></div><div style=\"font-size:10px;color:#334155;line-height:1.55\">Carriers invest billions in <strong>acquiring</strong> members but chronically under-invest in <strong>keeping</strong> them.</div></div><div style=\"background:white;border-radius:9px;border:0.5px solid #d4ead9;padding:9px 11px;margin-bottom:6px;display:flex;gap:9px;align-items:flex-start\"><div style=\"width:8px;height:8px;background:#1d9e75;border-radius:50%;flex-shrink:0;margin-top:3px\"></div><div style=\"font-size:10px;color:#334155;line-height:1.55\">The $60B\u2192$90B broker/FMO industry is explicitly incentivized to <strong>churn members at every AEP</strong>.</div></div><div style=\"background:white;border-radius:9px;border:0.5px solid #d4ead9;padding:9px 11px;margin-bottom:6px;display:flex;gap:9px;align-items:flex-start\"><div style=\"width:8px;height:8px;background:#1d9e75;border-radius:50%;flex-shrink:0;margin-top:3px\"></div><div style=\"font-size:10px;color:#334155;line-height:1.55\">Members feel like policy numbers, not people. Most <strong>never hear from their plan</strong> between enrollment and the next AEP.</div></div><div style=\"background:white;border-radius:9px;border:0.5px solid #d4ead9;padding:9px 11px;margin-bottom:6px;display:flex;gap:9px;align-items:flex-start\"><div style=\"width:8px;height:8px;background:#1d9e75;border-radius:50%;flex-shrink:0;margin-top:3px\"></div><div style=\"font-size:10px;color:#334155;line-height:1.55\">AI-powered enrollment tools are making <strong>broker outreach more aggressive</strong>. Retention needs to match that sophistication.</div></div><div style=\"font-size:9px;font-weight:700;color:#085041;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;margin-top:4px\">What makes BookCover different</div><div style=\"display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:0.5px solid #d4ead9\"><div style=\"color:#0F7B5C;font-weight:800;font-size:13px;flex-shrink:0\">&#10003;</div><div style=\"font-size:10px;color:#334155\">Individual member risk scores \u2014 not segment averages</div></div><div style=\"display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:0.5px solid #d4ead9\"><div style=\"color:#0F7B5C;font-weight:800;font-size:13px;flex-shrink:0\">&#10003;</div><div style=\"font-size:10px;color:#334155\">FHIR API integration \u2014 no custom IT project required</div></div><div style=\"display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:0.5px solid #d4ead9\"><div style=\"color:#0F7B5C;font-weight:800;font-size:13px;flex-shrink:0\">&#10003;</div><div style=\"font-size:10px;color:#334155\">Magic Link onboarding: member active in under 60 seconds</div></div><div style=\"display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:0.5px solid #d4ead9\"><div style=\"color:#0F7B5C;font-weight:800;font-size:13px;flex-shrink:0\">&#10003;</div><div style=\"font-size:10px;color:#334155\">Not in the enrollment business \u2014 we don\u2019t collect commissions</div></div><div style=\"display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:0.5px solid #d4ead9\"><div style=\"color:#0F7B5C;font-weight:800;font-size:13px;flex-shrink:0\">&#10003;</div><div style=\"font-size:10px;color:#334155\">CMS compliance monitoring built in, not bolted on</div></div><div style=\"display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:0.5px solid #d4ead9\"><div style=\"color:#0F7B5C;font-weight:800;font-size:13px;flex-shrink:0\">&#10003;</div><div style=\"font-size:10px;color:#334155\">Embedded consultants build and manage every campaign</div></div><div style=\"background:#f5faf6;border:0.5px solid #d4ead9;border-radius:9px;padding:9px 11px;margin-top:6px;margin-bottom:8px\"><div style=\"font-size:9px;font-weight:700;color:#085041;margin-bottom:6px\">Lines of Business</div><div style=\"display:flex;flex-wrap:wrap;gap:5px\"><div style=\"background:white;border:0.5px solid #d4ead9;border-radius:16px;padding:4px 10px;font-size:9px;font-weight:600;color:#334155\">Medicare Advantage</div><div style=\"background:white;border:0.5px solid #d4ead9;border-radius:16px;padding:4px 10px;font-size:9px;font-weight:600;color:#334155\">Medicaid / LTSS</div><div style=\"background:white;border:0.5px solid #d4ead9;border-radius:16px;padding:4px 10px;font-size:9px;font-weight:600;color:#334155\">Individual & Family</div><div style=\"background:white;border:0.5px solid #d4ead9;border-radius:16px;padding:4px 10px;font-size:9px;font-weight:600;color:#334155\">D-SNP</div><div style=\"background:white;border:0.5px solid #d4ead9;border-radius:16px;padding:4px 10px;font-size:9px;font-weight:600;color:#334155\">MA Transitions</div></div></div></div><div style=\"background:#f5faf6;border-top:1px solid #d4ead9;padding:5px;text-align:center;font-size:8px;color:#94A3B8;flex-shrink:0\">&#128274; SOC 2 Type II &middot; HIPAA-aligned &middot; Data hosted in United States</div></div><style>@keyframes spin{to{transform:rotate(360deg)}}</style>"];
