const REG_SCREENS=[{"id": "email-invite", "useCase": "M-001", "phase": "Step 1 \u2014 Invitation", "title": "Carrier Invitation Email", "subtitle": "Carrier name only \u00b7 No plan name \u00b7 Magic link from Your Health Plan", "explanation": "Your Health Plan sends a Magic Link invitation via BookCover. The email references the carrier name but NOT the plan tier (Gold Plus HMO) \u2014 plan data is not available until the member completes the OAuth connection. The invite is generic enough to work even if the member\u2019s plan changes.", "bullets": ["No plan name in subject or body \u2014 only carrier name (Your Health Plan)", "Magic link carries: member email, carrier ID, and expiry timestamp", "Secure JWT magic link \u00b7 valid 24 hours \u00b7 single use", "No app download or prior knowledge of BookCover required"], "frame": "email", "ctaSelector": "#btn-email-cta", "browserUrl": ""}, {"id": "invite-landing", "useCase": "M-001", "phase": "Step 2 \u2014 Link Validated", "title": "Magic Link Landing Page", "subtitle": "Invite verified instantly, carrier pre-populated", "explanation": "The moment Margaret taps the link, BookCover validates the JWT token server-side, extracts the carrier context, and pre-populates everything. She lands on a clean welcome screen \u2014 no search, no form, just a single clear choice.", "bullets": ["Token validated in under 300ms", "Carrier name and plan detected automatically", "Three registration methods offered \u2014 no preference required", "Token removed from browser URL bar immediately (security)"], "frame": "phone", "ctaSelector": "#btn-landing-fb", "browserUrl": ""}, {"id": "choose-method", "useCase": "M-003", "phase": "Step 3 \u2014 Registration Method", "title": "Choose Sign-In Method", "subtitle": "Margaret selects Facebook", "explanation": "All three registration methods are available. For this demo, Margaret selects Facebook. BookCover supports Google OAuth, Facebook OAuth, and email/password \u2014 the member chooses whatever is most convenient for them.", "bullets": ["Google, Facebook, or Email/Password \u2014 all supported", "Social login eliminates password creation friction", "No preference stored \u2014 member can switch in future", "Facebook path includes a required HIPAA privacy notice (next screen)"], "frame": "phone", "ctaSelector": "#btn-choose-fb", "browserUrl": ""}, {"id": "hipaa-notice", "useCase": "M-003", "phase": "Step 4 \u2014 HIPAA Notice", "title": "Facebook Privacy Notice", "subtitle": "Required before any Facebook OAuth redirect", "explanation": "Because Facebook is not a HIPAA Business Associate, BookCover shows a mandatory disclosure screen before redirecting to Facebook. This screen clearly distinguishes what is shared (name and email only) from what is never shared (any health data). It cannot be skipped.", "bullets": ["Facebook-specific screen \u2014 not shown for Google or Email", "Explicitly states: health data is NEVER shared with Facebook", "Member must tap 'Continue' \u2014 no auto-advance", "Logged server-side with timestamp for compliance audit trail"], "frame": "phone", "ctaSelector": "#btn-hipaa-continue", "browserUrl": ""}, {"id": "fb-redirect", "useCase": "M-003", "phase": "Step 5 \u2014 Facebook OAuth", "title": "Redirecting to Facebook", "subtitle": "Secure OAuth 2.0 handoff", "explanation": "BookCover redirects Margaret to Facebook's secure servers to authenticate. BookCover never sees her Facebook password. Only her name and email are requested via OAuth scope \u2014 no health data, no friends list, no activity.", "bullets": ["Standard OAuth 2.0 flow \u2014 state parameter for CSRF protection", "Only scopes: email + public_profile", "HIPAA notice flag verified server-side before generating OAuth URL", "BookCover waits for the secure callback from Facebook"], "frame": "phone", "ctaSelector": "#btn-fb-redirect-next", "browserUrl": ""}, {"id": "fb-verifying", "useCase": "M-003", "phase": "Step 6 \u2014 Identity Verified", "title": "Facebook Callback Processing", "subtitle": "Identity verified, plan membership matched", "explanation": "Margaret returns from Facebook. BookCover's backend exchanges the authorization code for her profile, then immediately checks her email against the carrier's member roster. Three steps happen in under two seconds \u2014 entirely automatic.", "bullets": ["Facebook identity verified via Graph API", "Email matched against Your Health Plan member roster", "BookCover account created and linked to carrier record", "PKCE not available for Facebook \u2014 CSRF protection via state param"], "frame": "phone", "ctaSelector": "#btn-fb-verify-next", "browserUrl": ""}, {"id": "profile-step1", "useCase": "M-007", "phase": "Step 7 \u2014 Profile Setup (1/2)", "title": "Confirm Your Information", "subtitle": "Name pre-filled from Facebook \u00b7 phone optional", "explanation": "Margaret's name is pre-populated from her Facebook account \u2014 she just confirms it. Adding a phone number is optional but unlocks SMS reminders. A progress indicator shows she's 50% through the one-time setup.", "bullets": ["First and last name pre-filled from Facebook id_token", "Phone number optional \u2014 enables SMS notification channel if provided", "No password created \u2014 Facebook is her authentication method", "All data saved in a single API call at Step 2 (not yet)"], "frame": "phone", "ctaSelector": "#btn-profile1-next", "browserUrl": ""}, {"id": "profile-step2", "useCase": "M-007", "phase": "Step 8 \u2014 Profile Setup (2/2)", "title": "Notification Preferences", "subtitle": "Email on by default \u00b7 SMS opt-in \u00b7 ToS required", "explanation": "Margaret selects her notification preferences and accepts the Terms of Service. Email is always enabled. SMS is opt-in only (TCPA compliance). The ToS version and acceptance timestamp are stored server-side for legal compliance. One API call saves everything.", "bullets": ["Email channel always on \u2014 cannot disable at setup", "SMS opt-in is explicit \u2014 never defaulted on (TCPA compliance)", "ToS acceptance timestamped server-side with version string", "Single PUT /api/v1/members/profile call saves PS-01 + PS-02 data together"], "frame": "phone", "ctaSelector": "#btn-profile2-finish", "browserUrl": ""}, {"id": "profile-complete", "useCase": "M-007", "phase": "Step 9 \u2014 Profile Complete", "title": "Profile Setup Complete", "subtitle": "Personalized confirmation \u00b7 next step clear", "explanation": "Profile setup is done. Margaret is greeted by name and guided directly to the next step \u2014 connecting her health plan plan. The carrier is already pre-populated from the original magic link, so she doesn't need to search for anything.", "bullets": ["Animated success state \u2014 600ms draw animation", "Personalized with first name from profile", "Carrier connection is the mandatory next step", "'Skip for now' creates a deferred flag \u2014 member is prompted again on every login"], "frame": "phone", "ctaSelector": "#btn-profile-complete-connect", "browserUrl": ""}, {"id": "dashboard-unconnected", "useCase": "M-008", "phase": "Step 10 \u2014 Dashboard (Unconnected)", "title": "Dashboard \u2014 Not Yet Connected", "subtitle": "Plan data unavailable \u00b7 Connect Your Health Plan CTA prominent", "explanation": "After completing registration, Margaret arrives at the dashboard for the first time. No plan data is available yet \u2014 carrier connection hasn\u2019t happened. All plan-dependent features are locked. A prominent \u2018Connect Your Health Plan\u2019 card is the primary action, with locked preview cards showing what she\u2019ll unlock.", "bullets": ["No plan name, deductibles, or coverage data shown \u2014 none available yet", "Prominent \u2018Connect Your Health Plan\u2019 CTA is the single primary action", "Four locked feature preview cards with lock icons (deductible, Rx, benefits, assistant)", "Demonstrates the system\u2019s empty-state UX before carrier API connection", "Tapping Connect flows into the carrier OAuth sequence (next screens)"], "frame": "phone"}, {"id": "carrier-prompt", "useCase": "Carrier Connection", "phase": "Step 10 \u2014 Connect Your Plan", "title": "Carrier Connection Prompt", "subtitle": "Value explained \u00b7 Your Health Plan pre-populated", "explanation": "BookCover explains exactly what the member gets by connecting their plan \u2014 in plain language. The carrier is already shown as Your Health Plan from the magic link context. One tap begins the SMART on FHIR OAuth connection.", "bullets": ["Carrier pre-populated \u2014 no manual search required", "Clear value proposition: deductibles, Rx, benefits, insights", "'Connect Now' triggers Path A of the carrier connection flow", "Privacy note: BookCover never sees the member's carrier password"], "frame": "phone", "ctaSelector": "#btn-carrier-prompt-connect", "browserUrl": ""}, {"id": "select-plan", "useCase": "Carrier Connection A1", "phase": "Step 11 \u2014 Confirm Plan", "title": "Select Your Plan", "subtitle": "Plan pre-populated \u00b7 Path A primary flow", "explanation": "Screen A1 of the carrier connection flow. The plan card is pre-populated \u2014 Margaret simply confirms and taps Connect. The system calls /api/v1/members/carrier-connection/intent which generates the SMART on FHIR OAuth URL and redirects.", "bullets": ["Plan details sourced from magic link token", "No manual carrier search needed in the primary flow", "'I don't have an account' link routes to Path B (account creation)", "API call generates SMART on FHIR authorization URL before redirect"], "frame": "phone", "ctaSelector": "#btn-select-plan-connect", "browserUrl": ""}, {"id": "redirecting-carrier", "useCase": "Carrier Connection A2", "phase": "Step 12 \u2014 Redirecting", "title": "Taking You to Your Health Plan", "subtitle": "SMART on FHIR OAuth redirect", "explanation": "Margaret is taken to Your Health Plan's own secure website. BookCover generates the SMART on FHIR authorization URL with specific scopes (Patient, Coverage, EOB, Medications) and redirects her browser. The carrier handles all authentication.", "bullets": ["SMART on FHIR OAuth 2.0 \u2014 Authorization Code flow", "Scopes: Patient.read \u00b7 Coverage.read \u00b7 ExplanationOfBenefit.read \u00b7 MedicationRequest.read", "BookCover stores the PKCE state for CSRF validation on callback", "Member prepared for what they'll see: username and password"], "frame": "phone", "ctaSelector": "#btn-redirect-next", "browserUrl": ""}, {"id": "carrier-login", "useCase": "Carrier Connection A3", "phase": "Step 13 \u2014 Carrier Login", "title": "Your Health Plan Login Page", "subtitle": "Carrier-hosted \u00b7 BookCover has zero control", "explanation": "Margaret is now on Your Health Plan's own website (yourhealthplan.com). BookCover has absolutely no visibility into this screen or the member's credentials. She logs in with her health plan username and password exactly as she would on the carrier's website directly.", "bullets": ["Carrier-hosted screen \u2014 not BookCover's UI", "BookCover never receives, stores, or sees the member's carrier password", "Browser URL bar shows yourhealthplan.com \u2014 not bookcover.com", "BSCA may show additional MFA challenge (carrier-controlled)"], "frame": "browser", "ctaSelector": "#btn-carrier-login-next", "browserUrl": "https://yourhealthplan.com/login"}, {"id": "carrier-consent", "useCase": "Carrier Connection A4", "phase": "Step 14 \u2014 Approve Access", "title": "Your Health Plan Access Consent", "subtitle": "Carrier-hosted \u00b7 specific scopes shown to member", "explanation": "Your Health Plan presents their standard SMART on FHIR consent screen. Margaret sees exactly what data BookCover is requesting access to. She taps 'Allow Access' and control returns to BookCover via the secure OAuth callback.", "bullets": ["Carrier-hosted consent screen \u2014 BookCover cannot customize it", "Member sees the exact data scopes being requested", "Tapping 'Allow Access' sends an authorization code to BookCover", "BookCover exchanges the code for a Bearer token on the server side only"], "frame": "browser", "ctaSelector": "#btn-consent-allow", "browserUrl": "https://yourhealthplan.com/oauth/authorize"}, {"id": "connecting", "useCase": "Carrier Connection A5", "phase": "Step 15 \u2014 Retrieving Data", "title": "Retrieving Plan Data", "subtitle": "OAuth complete \u00b7 FHIR API call in progress", "explanation": "OAuth is complete. BookCover is now calling the carrier\u2019s FHIR Patient-Access API. A progress list shows what\u2019s being retrieved in order: plan details, prescription history, benefits, and provider network. The spinner makes the async operation visible and reassuring.", "bullets": ["OAuth handshake complete \u2014 BookCover now has a scoped access token", "FHIR Coverage + CostToBeneficiary resources: plan name, deductible, OOPM", "MedicationRequest + ExplanationOfBenefit: active Rx and claim history", "Progress list animates step by step as each resource group loads", "Security note: carrier login credentials are never stored by BookCover"], "frame": "phone", "ctaSelector": "#btn-connecting-next", "browserUrl": ""}, {"id": "connected-success", "useCase": "Carrier Connection A6", "phase": "Step 16 \u2014 Plan Connected!", "title": "Plan Connected \u2014 First Data Reveal", "subtitle": "Gold Plus HMO appears here for the first time", "explanation": "The carrier API call is complete. This is the first screen where plan-specific data appears: Gold Plus HMO plan name, Plan ID H1234-001, effective date, and a summary of what was retrieved (3 Rx, 4 providers, 5 benefit items). Before this screen, no plan data was available in the BookCover system.", "bullets": ["\u2018Gold Plus HMO\u2019 appears for the first time \u2014 sourced from FHIR Coverage resource", "3 active prescriptions imported from MedicationRequest resources", "4 providers identified from ExplanationOfBenefit claim history", "5 benefit items loaded from Coverage.class benefit balance data", "All data encrypted at rest \u2014 member sees immediate confirmation"], "frame": "phone", "ctaSelector": "#btn-connected-dashboard", "browserUrl": ""}, {"id": "dashboard", "useCase": "M-009 (Dashboard)", "phase": "Step 17 \u2014 Member Dashboard", "title": "Member Dashboard", "subtitle": "Full experience unlocked \u2014 AI-powered health plan assistant", "explanation": "Margaret's complete member dashboard. Her plan data is live, personalized insights are active, and the AI chat assistant is ready to answer any question about her coverage in plain language. This is the end state of the registration journey \u2014 full value delivered.", "bullets": ["Live accumulator data refreshed on every login", "AI Chat answers coverage, drug, benefit, and provider questions", "Benefit utilization shows unused benefits with dollar values", "Proactive alerts for AEP, benefit expiry, and risk events"], "frame": "phone", "ctaSelector": null, "browserUrl": ""}];
