function switchFlow(n){
  if(n===activeFlow)return;
  activeFlow=n; cur=0;
  document.querySelectorAll('.flow-tab').forEach((b,i)=>b.classList.toggle('on',i===n));
  // Show/hide iPad vs info panel
  const ipadCol=document.querySelector('.ipad-col');
  const infoPanel=document.getElementById('info-panel');
  if(n===0){
    if(ipadCol) ipadCol.style.display='none';
    if(infoPanel) infoPanel.style.display='flex';
  } else {
    if(ipadCol) ipadCol.style.display='';
    if(infoPanel) infoPanel.style.display='none';
  }
  render(0,1);
}

